-- Decision 33: facilitator and group leader are picked from lists, never typed (generated by setup/build-people-sql.mjs).
CREATE TABLE facilitators ("name" TEXT PRIMARY KEY, "in_cohort" INTEGER NOT NULL DEFAULT 0, "order" INTEGER NOT NULL);
CREATE TABLE group_leaders ("batch_id" TEXT NOT NULL, "name" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1, "merged" TEXT NOT NULL DEFAULT '', "order" INTEGER NOT NULL, PRIMARY KEY ("batch_id", "name"));
ALTER TABLE accounts ADD COLUMN requested_facilitator TEXT NOT NULL DEFAULT '';
ALTER TABLE accounts ADD COLUMN requested_group_leader TEXT NOT NULL DEFAULT '';
ALTER TABLE memberships ADD COLUMN facilitator TEXT NOT NULL DEFAULT '';
UPDATE mirror_state SET dirty = dirty + 1 WHERE tbl IN ('accounts', 'memberships');
